-- ============================================================================
-- SHAREMONEY DATABASE SEED SCRIPT - GENERATION V19 (PRODUCTION LIVE SEED)
-- Generated Date: 2026-09-01
-- Features V19:
--   ✅ 5 Full Users with Real Data
--   ✅ User A: 56 Months History (01/2022 -> 09/2026)
--   ✅ User B: 13 Months History (09/2025 -> 09/2026, satisfies >= 12 months)
--   ✅ Users C, D, E: Multi-month active data
--   ✅ Cutoff at Live Date 01/09/2026
-- Parity: 100% Entity Parity with Spring Boot 3 (PostgreSQL Supabase / AWS EC2)
-- Bugfixes from V17:
--   ✅ FIX: Schema DEFAULT 'DYNAMIC' → 'FLEXIBLE' (prevents JPA BudgetType crash)
--   ✅ FIX: Added migration UPDATE to convert any existing 'DYNAMIC' rows
--   ✅ FIX: ALTER COLUMN type SET DEFAULT 'FLEXIBLE' for existing tables
-- Features:
--   1. Realtime Native Push Notifications (push_token in users + is_read unread badge)
--   2. Multi-Cycle Cashflow Engine (6 Weeks, 6 Months with Bi-directional Zero Baseline, 5 Years)
--   3. Dedicated Water Bill (Tiền nước Sawaco, droplets)
--   4. Designated Banks for A (MBBank 6617052004888), B (Techcombank), C (MSB)
--   5. Strict Real-time Cutoff at 26/08/2026
-- ============================================================================

-- 0. SCHEMA DEFINITIONS (CREATE TABLE IF NOT EXISTS)
-- ============================================================================

CREATE TABLE IF NOT EXISTS users (
    id UUID PRIMARY KEY,
    email VARCHAR(255) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    name VARCHAR(255) NOT NULL,
    avatar_url TEXT,
    phone VARCHAR(50),
    bank_bin VARCHAR(20),
    bank_account_no VARCHAR(50),
    bank_qr_url TEXT,
    push_token TEXT,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS wallets (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    balance NUMERIC(19, 4) NOT NULL DEFAULT 0,
    currency VARCHAR(10) NOT NULL DEFAULT 'VND',
    is_liability BOOLEAN NOT NULL DEFAULT FALSE,
    bank_bin VARCHAR(20),
    bank_account_no VARCHAR(50),
    bank_account_name VARCHAR(255),
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS categories (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    type VARCHAR(50) NOT NULL,
    icon_name VARCHAR(100),
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS payees (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    bank_bin VARCHAR(20),
    bank_name VARCHAR(100),
    bank_account VARCHAR(50),
    account_name VARCHAR(255),
    phone VARCHAR(50),
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS tags (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name VARCHAR(100) NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS external_loans (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    type VARCHAR(50) NOT NULL,
    counterparty_name VARCHAR(255) NOT NULL,
    principal_amount NUMERIC(19, 4) NOT NULL,
    interest_rate NUMERIC(5, 2) DEFAULT 0,
    start_date DATE NOT NULL,
    due_date DATE,
    description TEXT,
    is_settled BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS savings_goals (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    target_amount NUMERIC(19, 4) NOT NULL,
    current_amount NUMERIC(19, 4) NOT NULL DEFAULT 0,
    deadline_date DATE,
    status VARCHAR(50) NOT NULL DEFAULT 'IN_PROGRESS',
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS budgets (
    id UUID PRIMARY KEY,
    name VARCHAR(255),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    category_id UUID NOT NULL REFERENCES categories(id) ON DELETE CASCADE,
    limit_amount NUMERIC(19, 4) NOT NULL,
    month INTEGER NOT NULL,
    year INTEGER NOT NULL,
    type VARCHAR(50) NOT NULL DEFAULT 'FLEXIBLE',
    is_recurring BOOLEAN NOT NULL DEFAULT FALSE,
    due_day_of_month INTEGER,
    is_mandatory BOOLEAN NOT NULL DEFAULT FALSE,
    payee_bank_bin VARCHAR(20),
    payee_bank_account VARCHAR(50),
    payee_account_name VARCHAR(255),
    payee_id UUID REFERENCES payees(id) ON DELETE SET NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS transactions (
    id UUID PRIMARY KEY,
    wallet_id UUID NOT NULL REFERENCES wallets(id) ON DELETE CASCADE,
    amount NUMERIC(19, 4) NOT NULL,
    type VARCHAR(50) NOT NULL,
    category_id UUID NOT NULL REFERENCES categories(id) ON DELETE CASCADE,
    linked_budget_id UUID REFERENCES budgets(id) ON DELETE SET NULL,
    linked_expense_id UUID REFERENCES expenses(id) ON DELETE SET NULL,
    payee_id UUID REFERENCES payees(id) ON DELETE SET NULL,
    transaction_date TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    note TEXT,
    is_split BOOLEAN NOT NULL DEFAULT FALSE,
    exclude_from_budget BOOLEAN NOT NULL DEFAULT FALSE,
    payment_method VARCHAR(50) DEFAULT 'TRANSFER',
    is_auto_generated BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS transaction_splits (
    id UUID PRIMARY KEY,
    parent_transaction_id UUID NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,
    category_id UUID NOT NULL REFERENCES categories(id) ON DELETE CASCADE,
    amount NUMERIC(19, 4) NOT NULL,
    note TEXT,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS transaction_tags (
    transaction_id UUID NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,
    tag_id UUID NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
    PRIMARY KEY (transaction_id, tag_id)
);

CREATE TABLE IF NOT EXISTS groups (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    avatar_url TEXT,
    owner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS group_members (
    id UUID PRIMARY KEY,
    group_id UUID NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role VARCHAR(50) NOT NULL DEFAULT 'member',
    joined_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS expenses (
    id UUID PRIMARY KEY,
    group_id UUID NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
    paid_by UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    title VARCHAR(255) NOT NULL,
    amount NUMERIC(19, 4) NOT NULL,
    category VARCHAR(255) NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS expense_splits (
    id UUID PRIMARY KEY,
    expense_id UUID NOT NULL REFERENCES expenses(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    amount_owed NUMERIC(19, 4) NOT NULL,
    is_settled BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS payments (
    id UUID PRIMARY KEY,
    group_id UUID NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
    payer_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    receiver_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    amount NUMERIC(19, 4) NOT NULL,
    status VARCHAR(50) NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS notifications (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    message TEXT NOT NULL,
    type VARCHAR(50) NOT NULL,
    is_read BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS payment_orders (
    id UUID PRIMARY KEY,
    txn_ref VARCHAR(100) NOT NULL,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    type VARCHAR(50) NOT NULL,
    amount NUMERIC(19, 4) NOT NULL,
    wallet_id UUID,
    category_id UUID,
    budget_id UUID,
    group_id UUID,
    creditor_id UUID,
    status VARCHAR(50) NOT NULL,
    vnp_transaction_no VARCHAR(100),
    vnp_bank_code VARCHAR(50),
    vnp_card_type VARCHAR(50),
    vnp_pay_date VARCHAR(50),
    vnp_response_code VARCHAR(50),
    vnp_order_info TEXT,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    expired_at TIMESTAMP WITHOUT TIME ZONE,
    paid_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE IF NOT EXISTS refresh_tokens (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token VARCHAR(255) NOT NULL UNIQUE,
    expiry_date TIMESTAMP WITH TIME ZONE NOT NULL,
    revoked BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Tự động đồng bộ các cột mới nếu bảng đã tồn tại sẵn
ALTER TABLE IF EXISTS users ADD COLUMN IF NOT EXISTS push_token TEXT;
ALTER TABLE IF EXISTS users ADD COLUMN IF NOT EXISTS bank_bin VARCHAR(20);
ALTER TABLE IF EXISTS users ADD COLUMN IF NOT EXISTS bank_account_no VARCHAR(50);
ALTER TABLE IF EXISTS users ADD COLUMN IF NOT EXISTS bank_qr_url TEXT;
ALTER TABLE IF EXISTS users ADD COLUMN IF NOT EXISTS bank_account_name VARCHAR(100);
ALTER TABLE IF EXISTS users ADD COLUMN IF NOT EXISTS savings_bank_bin VARCHAR(20);
ALTER TABLE IF EXISTS users ADD COLUMN IF NOT EXISTS savings_bank_account_no VARCHAR(50);
ALTER TABLE IF EXISTS users ADD COLUMN IF NOT EXISTS savings_bank_account_name VARCHAR(100);


ALTER TABLE IF EXISTS wallets ADD COLUMN IF NOT EXISTS bank_bin VARCHAR(20);
ALTER TABLE IF EXISTS wallets ADD COLUMN IF NOT EXISTS bank_account_no VARCHAR(50);
ALTER TABLE IF EXISTS wallets ADD COLUMN IF NOT EXISTS bank_account_name VARCHAR(255);

ALTER TABLE IF EXISTS budgets ADD COLUMN IF NOT EXISTS payee_bank_bin VARCHAR(20);
ALTER TABLE IF EXISTS budgets ADD COLUMN IF NOT EXISTS payee_bank_account VARCHAR(50);
ALTER TABLE IF EXISTS budgets ADD COLUMN IF NOT EXISTS payee_account_name VARCHAR(255);
ALTER TABLE IF EXISTS budgets ADD COLUMN IF NOT EXISTS payee_id UUID;
ALTER TABLE IF EXISTS budgets ADD COLUMN IF NOT EXISTS is_mandatory BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE IF EXISTS budgets ADD COLUMN IF NOT EXISTS due_day_of_month INTEGER;

ALTER TABLE IF EXISTS transactions ADD COLUMN IF NOT EXISTS linked_expense_id UUID;
ALTER TABLE IF EXISTS transactions ADD COLUMN IF NOT EXISTS payment_method VARCHAR(50) DEFAULT 'TRANSFER';

ALTER TABLE IF EXISTS transaction_splits ADD COLUMN IF NOT EXISTS parent_transaction_id UUID;
DO $$ 
BEGIN 
    IF EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'transaction_splits' AND column_name = 'transaction_id'
    ) THEN
        UPDATE transaction_splits SET parent_transaction_id = transaction_id WHERE parent_transaction_id IS NULL;
    END IF;
END $$;

-- ✅ V18 CRITICAL FIX: Force DEFAULT and existing data to FLEXIBLE (prevents JPA BudgetType.DYNAMIC crash)
ALTER TABLE IF EXISTS budgets ALTER COLUMN type SET DEFAULT 'FLEXIBLE';
UPDATE budgets SET type = 'FLEXIBLE' WHERE type = 'DYNAMIC';

-- Dọn dẹp dữ liệu cũ an toàn
DO $$ 
DECLARE 
    tbl text;
    tbls text[] := ARRAY['transaction_tags', 'refresh_tokens', 'payment_orders', 'transaction_splits', 'transactions', 'expense_splits', 'expenses', 'payments', 'group_members', 'groups', 'external_loans', 'savings_goals', 'budgets', 'categories', 'payees', 'tags', 'notifications', 'wallets', 'users'];
BEGIN 
    FOREACH tbl IN ARRAY tbls LOOP
        IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = tbl) THEN
            EXECUTE 'DELETE FROM ' || quote_ident(tbl);
        END IF;
    END LOOP;
END $$;

